#include "include/DiscoveryBridge.h"
#include "vlc.h"
#include "libs.h"
#include "libs/input.h"
#include "libvlc_internal.h"
#include <vlc_services_discovery.h>
#include <vlc_events.h>
#include <stdatomic.h>

typedef struct Service{struct Service*next;struct VelaDiscovery*host;services_discovery_t*sd;char*name;char*description;int identifier;}Service;
typedef struct Record{input_item_t*item;int id,parent;char*source;bool hidden;}Record;
struct VelaDiscovery{atomic_int references;libvlc_instance_t*instance;vlc_object_t*object;pthread_mutex_t lock,operations;Service*services;Record*records;size_t count;int serial;};
static void tree_added(const vlc_event_t*,void*);
VelaDiscovery*vela_discovery_new(libvlc_instance_t*instance){VelaDiscovery*d=calloc(1,sizeof(*d));if(!d)return NULL;atomic_init(&d->references,1);d->serial=1000000;d->instance=instance;libvlc_retain(instance);d->object=vlc_object_create((vlc_object_t*)instance->p_libvlc_int,sizeof(vlc_object_t));if(!d->object){libvlc_release(instance);free(d);return NULL;}
 /* This context provides playlist variables and SDK service callbacks. It is
    never cast to a core playlist implementation or used for playback. */
 d->object->obj.object_type="playlist";pthread_mutex_init(&d->lock,NULL);pthread_mutex_init(&d->operations,NULL);return d;}
void vela_discovery_retain(VelaDiscovery*d){if(d)atomic_fetch_add(&d->references,1);}
void*vela_discovery_object(VelaDiscovery*d){return d?d->object:NULL;}
static int find_record(VelaDiscovery*d,input_item_t*item){for(size_t i=0;i<d->count;i++)if(d->records[i].item==item)return (int)i;return -1;}
static int add_record(VelaDiscovery*d,input_item_t*parent,input_item_t*item,const char*source){pthread_mutex_lock(&d->lock);int found=find_record(d,item),p=find_record(d,parent);int parent_id=p>=0?d->records[p].id:0;if(found>=0){d->records[found].hidden=false;if(parent_id)d->records[found].parent=parent_id;int id=d->records[found].id;pthread_mutex_unlock(&d->lock);return id;}Record*records=realloc(d->records,(d->count+1)*sizeof(*records));if(!records){pthread_mutex_unlock(&d->lock);return -1;}d->records=records;Record*r=&d->records[d->count++];*r=(Record){input_item_Hold(item),++d->serial,parent_id,strdup(source),false};int id=r->id;pthread_mutex_unlock(&d->lock);vlc_event_attach(&item->event_manager,vlc_InputItemSubItemTreeAdded,tree_added,d);return id;}
static void add_tree(VelaDiscovery*d,input_item_node_t*node,const char*source,int depth){if(depth>64)return;for(int i=0;i<node->i_children;i++){input_item_node_t*child=node->pp_children[i];add_record(d,node->p_item,child->p_item,source);add_tree(d,child,source,depth+1);}}
static void tree_added(const vlc_event_t*event,void*context){VelaDiscovery*d=context;input_item_node_t*node=event->u.input_item_subitem_tree_added.p_root;pthread_mutex_lock(&d->lock);int index=find_record(d,node->p_item);char*source=index>=0?strdup(d->records[index].source):NULL;pthread_mutex_unlock(&d->lock);if(source){add_tree(d,node,source,0);free(source);}}
static void item_added(services_discovery_t*sd,input_item_t*parent,input_item_t*item,const char*category){Service*s=sd->owner.sys;(void)category;add_record(s->host,parent,item,s->name);}
void vela_discovery_hide(VelaDiscovery*d,int id){pthread_mutex_lock(&d->lock);for(size_t i=0;i<d->count;i++){Record*r=&d->records[i];if(r->id==id||r->parent==id){r->hidden=true;}}pthread_mutex_unlock(&d->lock);}
static void item_removed(services_discovery_t*sd,input_item_t*item){Service*s=sd->owner.sys;VelaDiscovery*d=s->host;pthread_mutex_lock(&d->lock);int index=find_record(d,item);int id=index>=0?d->records[index].id:0;pthread_mutex_unlock(&d->lock);if(id)vela_discovery_hide(d,id);}
int vela_discovery_add(VelaDiscovery*d,const char*name){pthread_mutex_lock(&d->operations);pthread_mutex_lock(&d->lock);for(Service*s=d->services;s;s=s->next)if(!strcmp(s->name,name)){pthread_mutex_unlock(&d->lock);pthread_mutex_unlock(&d->operations);return 0;}pthread_mutex_unlock(&d->lock);Service*s=calloc(1,sizeof(*s));if(!s){pthread_mutex_unlock(&d->operations);return VLC_ENOMEM;}s->host=d;s->name=strdup(name);struct services_discovery_owner_t owner={s,item_added,item_removed};s->sd=vlc_sd_Create(d->object,name,&owner);if(!s->sd){free(s->name);free(s);pthread_mutex_unlock(&d->operations);return VLC_EGENERIC;}s->description=strdup(s->sd->description?s->sd->description:name);pthread_mutex_lock(&d->lock);s->identifier=++d->serial;s->next=d->services;d->services=s;pthread_mutex_unlock(&d->lock);pthread_mutex_unlock(&d->operations);return VLC_SUCCESS;}
int vela_discovery_remove(VelaDiscovery*d,const char*name){pthread_mutex_lock(&d->operations);pthread_mutex_lock(&d->lock);Service**link=&d->services;while(*link&&strcmp((*link)->name,name))link=&(*link)->next;Service*s=*link;if(!s){pthread_mutex_unlock(&d->lock);pthread_mutex_unlock(&d->operations);return VLC_EGENERIC;}*link=s->next;for(size_t i=0;i<d->count;i++)if(!strcmp(d->records[i].source,name))d->records[i].hidden=true;pthread_mutex_unlock(&d->lock);vlc_sd_Destroy(s->sd);free(s->description);free(s->name);free(s);pthread_mutex_unlock(&d->operations);return VLC_SUCCESS;}
bool vela_discovery_loaded(VelaDiscovery*d,const char*name){bool result=false;pthread_mutex_lock(&d->lock);for(Service*s=d->services;s;s=s->next)if(!strcmp(s->name,name)){result=true;break;}pthread_mutex_unlock(&d->lock);return result;}
char*vela_discovery_uri(VelaDiscovery*d,int id){input_item_t*item=NULL;pthread_mutex_lock(&d->lock);for(size_t i=0;i<d->count;i++)if(d->records[i].id==id&&!d->records[i].hidden){item=input_item_Hold(d->records[i].item);break;}pthread_mutex_unlock(&d->lock);if(!item)return NULL;char*uri=input_item_GetURI(item);input_item_Release(item);return uri;}
static void push_children(lua_State*L,Record*records,size_t count,int parent,const char*source,int depth){lua_newtable(L);if(depth>64)return;int index=0;for(size_t i=0;i<count;i++){Record*r=&records[i];if(r->hidden||r->parent!=parent||strcmp(r->source,source))continue;lua_newtable(L);lua_pushinteger(L,r->id);lua_setfield(L,-2,"id");char*name=input_item_GetTitleFbName(r->item);lua_pushstring(L,name);free(name);lua_setfield(L,-2,"name");char*uri=input_item_GetURI(r->item);lua_pushstring(L,uri);free(uri);lua_setfield(L,-2,"path");lua_pushnumber(L,(double)input_item_GetDuration(r->item)/1000000);lua_setfield(L,-2,"duration");lua_newtable(L);lua_setfield(L,-2,"flags");lua_pushinteger(L,0);lua_setfield(L,-2,"nb_played");luaopen_input_item(L,r->item);push_children(L,records,count,r->id,source,depth+1);if(lua_objlen(L,-1))lua_setfield(L,-2,"children");else lua_pop(L,1);lua_rawseti(L,-2,++index);}}
int vela_discovery_lua_get(lua_State*L,VelaDiscovery*d,const char*which){pthread_mutex_lock(&d->lock);Service*service=NULL;for(Service*s=d->services;s;s=s->next)if(!strcasecmp(which,s->name)||!strcasecmp(which,s->description)){service=s;break;}if(!service){pthread_mutex_unlock(&d->lock);lua_pushnil(L);return 1;}int identifier=service->identifier;char*source=strdup(service->name),*description=strdup(service->description);size_t count=d->count;Record*records=calloc(count?count:1,sizeof(*records));if(records)for(size_t i=0;i<count;i++){records[i]=d->records[i];records[i].item=input_item_Hold(records[i].item);records[i].source=strdup(records[i].source);}pthread_mutex_unlock(&d->lock);if(!records){free(source);free(description);return luaL_error(L,"Out of memory reading service discovery");}lua_newtable(L);lua_pushstring(L,description);lua_setfield(L,-2,"name");lua_pushinteger(L,identifier);lua_setfield(L,-2,"id");push_children(L,records,count,0,source,0);lua_setfield(L,-2,"children");for(size_t i=0;i<count;i++){input_item_Release(records[i].item);free(records[i].source);}free(records);free(source);free(description);return 1;}
int vela_discovery_lua_roots(lua_State*L,VelaDiscovery*d){pthread_mutex_lock(&d->lock);size_t count=0;for(Service*s=d->services;s;s=s->next)count++;char**names=calloc(count?count:1,sizeof(char*));size_t n=0;if(names)for(Service*s=d->services;s;s=s->next)names[n++]=strdup(s->name);pthread_mutex_unlock(&d->lock);lua_newtable(L);int index=0;for(size_t i=0;i<n;i++){vela_discovery_lua_get(L,d,names[i]);if(!lua_isnil(L,-1))lua_rawseti(L,-2,++index);else lua_pop(L,1);free(names[i]);}free(names);return 1;}
void vela_discovery_release(VelaDiscovery*d){if(!d||atomic_fetch_sub(&d->references,1)!=1)return;while(d->services){char*name=strdup(d->services->name);vela_discovery_remove(d,name);free(name);}for(size_t i=0;i<d->count;i++){Record*r=&d->records[i];vlc_event_detach(&r->item->event_manager,vlc_InputItemSubItemTreeAdded,tree_added,d);input_item_Release(r->item);free(r->source);}free(d->records);pthread_mutex_destroy(&d->lock);pthread_mutex_destroy(&d->operations);vlc_object_release(d->object);libvlc_release(d->instance);free(d);}
